<div class="admin-pagehead"><div><span class="micro-label">DATOS INSTITUCIONALES</span><h1>Configuración del refugio</h1><p>Edita información oficial, redes sociales y medios de colaboración.</p></div><a class="btn btn-outline" href="/admin/tema">Configurar tema ↗</a></div><section class="admin-panel"><form class="editor-form" action="/admin/configuracion" method="post"><?= csrf_field() ?><?php foreach([['Información general',['nombre_refugio'=>'Nombre público del refugio','frase_institucional'=>'Frase institucional','descripcion_breve'=>'Descripción breve','mision'=>'Misión','historia'=>'Historia institucional']],['Contacto',['telefono'=>'Teléfono','whatsapp'=>'WhatsApp','correo_contacto'=>'Correo público','direccion_publica'=>'Dirección pública','horario_atencion'=>'Horarios']],['Redes sociales',['facebook_url'=>'Facebook','instagram_url'=>'Instagram','tiktok_url'=>'TikTok']],['Medios bancarios',['banco_nombre'=>'Banco','banco_titular'=>'Titular','banco_numero_cuenta'=>'Número de cuenta','banco_tipo_cuenta'=>'Tipo de cuenta','banco_instrucciones'=>'Instrucciones de aportes']]] as [$section,$fields]):?><h2><?= e($section) ?></h2><div class="form-pair"><?php foreach($fields as $key=>$label):?><label><?= e($label) ?><?php if(in_array($key,['descripcion_breve','mision','historia','banco_instrucciones'],true)):?><textarea name="<?= e($key) ?>"><?= e($settings[$key]??'') ?></textarea><?php else: ?><input type="text" name="<?= e($key) ?>" value="<?= e($settings[$key]??'') ?>"><?php endif ?></label><?php endforeach ?></div><?php endforeach ?><label class="toggle-row"><input type="checkbox" name="donaciones_habilitadas" value="1" <?= !empty($settings['donaciones_habilitadas'])?'checked':'' ?>><span>Habilitar registro de aportes monetarios <small>Solo cuando los datos bancarios estén completos y comprobados.</small></span></label><button class="btn btn-primary" type="submit">Guardar configuración ↗</button></form></section>
